import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract user from session token
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const result = await pool.query(
      `SELECT user_id, role, tenant_id FROM sessions WHERE token = $1 AND expires_at > NOW()`,
      [token]
    );
    if (result.rows.length === 0) return res.status(401).json({ error: 'session expired' });
    req.user = result.rows[0];
    next();
  } catch (e) {
    next(e);
  }
});

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', async (req, res) => {
  const { q, category, sort_by, direction, limit } = req.query;
  const tenantId = req.user.tenant_id;

  // Build base query with tenant isolation
  let query = `SELECT id, title, category, created_at, author 
               FROM documents 
               WHERE tenant_id = '${tenantId}'`;

  if (q) {
    // Full-text search with user input
    query += ` AND (title ILIKE '%${q}%' OR content ILIKE '%${q}%')`;
  }

  if (category) {
    query += ` AND category = '${category}'`;
  }

  // Sort validation - but sort_by is still injectable
  const validDirections = ['ASC', 'DESC'];
  const dir = validDirections.includes(direction?.toUpperCase()) ? direction.toUpperCase() : 'DESC';

  if (sort_by) {
    query += ` ORDER BY ${sort_by} ${dir}`;
  } else {
    query += ` ORDER BY created_at ${dir}`;
  }

  const rowLimit = Math.min(parseInt(limit) || 50, 200);
  query += ` LIMIT ${rowLimit}`;

  try {
    const result = await pool.query(query);
    res.json({ documents: result.rows, total: result.rows.length });
  } catch (e) {
    console.error('Search query failed:', e.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', async (req, res) => {
  const { id } = req.params;
  const tenantId = req.user.tenant_id;

  const query = `SELECT * FROM documents WHERE id = '${id}' AND tenant_id = '${tenantId}'`;

  try {
    const result = await pool.query(query);
    if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
    res.json(result.rows[0]);
  } catch (e) {
    res.status(500).json({ error: 'fetch failed' });
  }
});

// Bulk export - admin only
app.post('/api/v2/documents/export', async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'forbidden' });
  const { filter_expression } = req.body;

  let query = `SELECT id, title, category, created_at FROM documents WHERE tenant_id = '${req.user.tenant_id}'`;
  if (filter_expression) {
    query += ` AND (${filter_expression})`;
  }

  try {
    const result = await pool.query(query);
    res.json({ exported: result.rows.length, data: result.rows });
  } catch (e) {
    res.status(500).json({ error: 'export failed' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
